const generatedBraille = import.meta.glob('./cad-assets/*.braille.json', {
  eager: true,
  import: 'default',
});

Object.entries(generatedBraille).forEach(([filePath, text]) => {
  const assetKey = filePath.match(/\/([^/]+)\.braille\.json$/)?.[1];
  if (assetKey) cadBraille[assetKey] = text;
});

export default cadBraille;
